    {
      "scope": "DIFF",
      "severity": "high",
      "reference": "DailyRisk.mqh:4",
      "problem": "The helper allows new entries while risk state is unrestored, reversing the last known good behavior and permitting added exposure before the daily drawdown is known.",
      "example": "AllowNewEntry(0.0, 5.0, false) must return false. The changed code returns true."
    },
    {
      "scope": "DIFF",
      "severity": "medium",
      "reference": "DailyRisk.mqh:5",
      "problem": "The inclusive comparison allows new entries at the drawdown limit, contrary to the below-limit contract and the last known good behavior.",
      "example": "AllowNewEntry(5.0, 5.0, true) must return false. The changed code returns true."
    }
  ]
